from collections import Counter

def learn_bpe(words, merges=3):
    corpus = [(tuple(word), count) for word, count in words.items()]
    rules = []
    for _ in range(merges):
        counts = Counter()
        for symbols, freq in corpus:
            for pair in zip(symbols, symbols[1:]):
                counts[pair] += freq
        if not counts:
            break
        pair = sorted(counts, key=lambda p: (-counts[p], p))[0]
        rules.append(pair)
        updated = []
        for symbols, freq in corpus:
            out = []; i = 0
            while i < len(symbols):
                if i+1 < len(symbols) and (symbols[i], symbols[i+1]) == pair:
                    out.append(symbols[i] + symbols[i+1]); i += 2
                else:
                    out.append(symbols[i]); i += 1
            updated.append((tuple(out), freq))
        corpus = updated
    return rules, corpus

rules, corpus = learn_bpe({'low': 5, 'lower': 2}, 2)
assert rules[0] == ('l', 'o')
assert rules[1] == ('lo', 'w')
assert corpus[0][0][0] == 'low'
print(rules, corpus)

import math

def dot(a, b):
    assert len(a) == len(b)
    return sum(x*y for x, y in zip(a,b))

def cosine(a, b):
    na = math.sqrt(dot(a,a)); nb = math.sqrt(dot(b,b))
    if na == 0 or nb == 0:
        raise ValueError('cosine undefined for zero vectors')
    return dot(a,b)/(na*nb)

q = (1., 1.)
a = (2., 0.)
b = (.8, .8)
assert dot(q,a) > dot(q,b)
assert cosine(q,b) > cosine(q,a)
assert math.isclose(cosine(q,a), 2/math.sqrt(8))

items = {'A':a, 'B':b}
ranked = sorted(items, key=lambda k: (-cosine(q, items[k]), k))
assert ranked == ['B','A']
print(ranked)
